        const seek = opts.seek === "present" ? "present" : "any";
        const target = seek === "present"
            ? "neighbor"
            : (opts.target ?? "reachable");
        const isInDialQueue = (h) => this.components.connectionManager
            .getDialQueue()
            .some((x) => x.peerId && getPublicKeyFromPeerId(x.peerId).hashcode() === h);
        const hasConnection = (h) => this.components.connectionManager
            .getConnections()
            .some((x) => getPublicKeyFromPeerId(x.remotePeer).hashcode() === h);
        const isPresent = (h) => isInDialQueue(h) || hasConnection(h);
        const isReachable = (h) => this.routes.isReachable(this.publicKeyHash, h, 0);
        const isNeighbor = (h) => {
            const s = this.peers.get(h);
            return !!s && s.isReadable && s.isWritable;
        };
        const eventsFor = (t) => t === "neighbor"
            ? ["peer:reachable", "stream:outbound", "stream:inbound"]
            : ["peer:reachable"];
        const reached = (h, t) => t === "neighbor" ? isNeighbor(h) : isReachable(h);
